def homotopyPrism (H : f₀.Homotopy f₁) {n : ℕ} (i : Fin (n + 1))
    (simplex : SingularSimplex X n) : SingularSimplex Y (n + 1) :=
  (H.toContinuousMap.comp ((ContinuousMap.id unitInterval).prodMap simplex)).comp (prism i)

